def _get_field(field_name: str) -> Field:
    schema = EntTestObjectSchema()
    fields = schema.get_all_fields()
    field = next(
        filter(
            lambda field: field.name == field_name,
            fields,
        )
    )
    if not field:
        raise ValueError(f"Unknown field: {field_name}")
    return field
